from b200probe import cuda_kernel, sass
import torch, time
src = r'''
extern "C" __global__ void ffma(float* out, int iters, float a, float b) {
  float x0=threadIdx.x, x1=x0+1, x2=x0+2, x3=x0+3, x4=x0+4, x5=x0+5, x6=x0+6, x7=x0+7;
  for (int i=0;i<iters;i++){
    x0=fmaf(x0,a,b); x1=fmaf(x1,a,b); x2=fmaf(x2,a,b); x3=fmaf(x3,a,b);
    x4=fmaf(x4,a,b); x5=fmaf(x5,a,b); x6=fmaf(x6,a,b); x7=fmaf(x7,a,b);
  }
  if (x0+x1+x2+x3+x4+x5+x6+x7 == 12345.f) out[0]=1;
}
extern "C" __global__ void ffma2(float* out, int iters, float a, float b) {
  float x0=threadIdx.x, x1=x0+1, x2=x0+2, x3=x0+3, x4=x0+4, x5=x0+5, x6=x0+6, x7=x0+7;
  for (int i=0;i<iters;i++){
    asm volatile("{.reg .b64 p0,p1,p2,p3,pa,pb;\n"
      "mov.b64 pa,{%8,%8}; mov.b64 pb,{%9,%9};\n"
      "mov.b64 p0,{%0,%1}; mov.b64 p1,{%2,%3}; mov.b64 p2,{%4,%5}; mov.b64 p3,{%6,%7};\n"
      "fma.rn.f32x2 p0,p0,pa,pb; fma.rn.f32x2 p1,p1,pa,pb; fma.rn.f32x2 p2,p2,pa,pb; fma.rn.f32x2 p3,p3,pa,pb;\n"
      "mov.b64 {%0,%1},p0; mov.b64 {%2,%3},p1; mov.b64 {%4,%5},p2; mov.b64 {%6,%7},p3;}\n"
      : "+f"(x0),"+f"(x1),"+f"(x2),"+f"(x3),"+f"(x4),"+f"(x5),"+f"(x6),"+f"(x7) : "f"(a),"f"(b));
  }
  if (x0+x1+x2+x3+x4+x5+x6+x7 == 12345.f) out[0]=1;
}
'''
out = torch.zeros(1, device='cuda')
for name in ('ffma','ffma2'):
    k = cuda_kernel(src, name)
    iters=20000
    grid=148*8; block=256
    k((grid,1,1),(block,1,1), out, iters, 0.999, 0.001); torch.cuda.synchronize()
    t0=time.perf_counter(); 
    for _ in range(5): k((grid,1,1),(block,1,1), out, iters, 0.999, 0.001)
    torch.cuda.synchronize(); dt=(time.perf_counter()-t0)/5
    fl = grid*block*iters*8*2
    print(name, f"{dt*1e3:.2f} ms  {fl/dt/1e12:.1f} TFLOP/s")
s = sass(src)
