#include <cuda_runtime.h>
#include <cublasLt.h>
#include <cstdint>
#include <cstdio>
#include <map>
#include <mutex>

// AdaLayerNormZero modulation: out_i = emb @ W_i^T + bias_i for i in 0..5, fp32 FFMA (CUBLAS_COMPUTE_32F).
// Column-major view: D_i (N x B, ld N) = op_T(W_i as K x N, ld K) * (emb as K x B, ld K) + bias_i (per row).

namespace {
constexpr int kD = 3072;   // inner_dim
constexpr int kChunks = 6;

struct Plan {
  cublasLtMatmulDesc_t desc = nullptr;
  cublasLtMatrixLayout_t la = nullptr, lb = nullptr, lc = nullptr;
  cublasLtMatmulAlgo_t algo;
  bool have_algo = false;
};

cublasLtHandle_t g_handle = nullptr;
std::mutex g_mu;
std::map<int, Plan> g_plans;   // keyed on batch size (shape only)

Plan& get_plan(int B, size_t ws_bytes) {
  std::lock_guard<std::mutex> lk(g_mu);
  if (!g_handle) cublasLtCreate(&g_handle);
  auto it = g_plans.find(B);
  if (it != g_plans.end()) return it->second;
  Plan p;
  cublasLtMatmulDescCreate(&p.desc, CUBLAS_COMPUTE_32F, CUDA_R_32F);
  cublasOperation_t ta = CUBLAS_OP_T, tb = CUBLAS_OP_N;
  cublasLtMatmulDescSetAttribute(p.desc, CUBLASLT_MATMUL_DESC_TRANSA, &ta, sizeof(ta));
  cublasLtMatmulDescSetAttribute(p.desc, CUBLASLT_MATMUL_DESC_TRANSB, &tb, sizeof(tb));
  cublasLtEpilogue_t epi = CUBLASLT_EPILOGUE_BIAS;
  cublasLtMatmulDescSetAttribute(p.desc, CUBLASLT_MATMUL_DESC_EPILOGUE, &epi, sizeof(epi));
  // A = W_i stored as K x N (row-major [N,K]), B = emb stored as K x B (row-major [B,K]), D = N x B (row-major [B,N]).
  cublasLtMatrixLayoutCreate(&p.la, CUDA_R_32F, kD, kD, kD);
  cublasLtMatrixLayoutCreate(&p.lb, CUDA_R_32F, kD, B, kD);
  cublasLtMatrixLayoutCreate(&p.lc, CUDA_R_32F, kD, B, kD);
  cublasLtMatmulPreference_t pref;
  cublasLtMatmulPreferenceCreate(&pref);
  cublasLtMatmulPreferenceSetAttribute(pref, CUBLASLT_MATMUL_PREF_MAX_WORKSPACE_BYTES, &ws_bytes, sizeof(ws_bytes));
  cublasLtMatmulHeuristicResult_t res[1];
  int n = 0;
  if (cublasLtMatmulAlgoGetHeuristic(g_handle, p.desc, p.la, p.lb, p.lc, p.lc, pref, 1, res, &n) == CUBLAS_STATUS_SUCCESS && n > 0) {
    p.algo = res[0].algo;
    p.have_algo = true;
  }
  cublasLtMatmulPreferenceDestroy(pref);
  return g_plans.emplace(B, p).first->second;
}
}  // namespace

extern "C" int adamod_launch(const float* emb, const float* weight, const float* bias, float* const* outs, int B,
                             void* ws, size_t ws_bytes, cudaStream_t stream) {
  Plan& p = get_plan(B, ws_bytes);
  const float alpha = 1.f, beta = 0.f;
  for (int i = 0; i < kChunks; ++i) {
    const float* wi = weight + (size_t)i * kD * kD;
    const float* bi = bias + (size_t)i * kD;
    float* di = outs[i];
    {
      std::lock_guard<std::mutex> lk(g_mu);
      cublasLtMatmulDescSetAttribute(p.desc, CUBLASLT_MATMUL_DESC_BIAS_POINTER, &bi, sizeof(bi));
      cublasStatus_t st = cublasLtMatmul(g_handle, p.desc, &alpha, wi, p.la, emb, p.lb, &beta, di, p.lc, di, p.lc,
                                         p.have_algo ? &p.algo : nullptr, ws, ws_bytes, stream);
      if (st != CUBLAS_STATUS_SUCCESS) return (int)st;
    }
  }
  return 0;
}

#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>

extern "C" int adamod_launch(const float* emb, const float* weight, const float* bias, float* const* outs, int B,
                             void* ws, size_t ws_bytes, cudaStream_t stream);

void run(torch::Tensor emb, torch::Tensor weight, torch::Tensor bias,
         torch::Tensor shift_msa, torch::Tensor scale_msa, torch::Tensor gate_msa,
         torch::Tensor shift_mlp, torch::Tensor scale_mlp, torch::Tensor gate_mlp) {
  TORCH_CHECK(emb.is_cuda() && emb.dtype() == torch::kFloat32 && emb.is_contiguous(), "emb must be contiguous fp32 cuda");
  TORCH_CHECK(weight.is_contiguous() && weight.dtype() == torch::kFloat32, "weight must be contiguous fp32");
  TORCH_CHECK(bias.is_contiguous() && bias.dtype() == torch::kFloat32, "bias must be contiguous fp32");
  TORCH_CHECK(emb.dim() == 2 && emb.size(1) == 3072, "emb must be [B, 3072]");
  TORCH_CHECK(weight.size(0) == 6 * 3072 && weight.size(1) == 3072, "weight must be [18432, 3072]");
  const int B = (int)emb.size(0);
  torch::Tensor outs_t[6] = {shift_msa, scale_msa, gate_msa, shift_mlp, scale_mlp, gate_mlp};
  float* outs[6];
  for (int i = 0; i < 6; ++i) {
    TORCH_CHECK(outs_t[i].is_contiguous() && outs_t[i].size(0) == B && outs_t[i].size(1) == 3072, "bad output shape");
    outs[i] = outs_t[i].data_ptr<float>();
  }
  const c10::cuda::OptionalCUDAGuard guard(emb.device());
  cudaStream_t stream = at::cuda::getCurrentCUDAStream().stream();
  const size_t ws_bytes = size_t(32) << 20;
  torch::Tensor ws = torch::empty({(long)ws_bytes}, emb.options().dtype(torch::kUInt8));
  int st = adamod_launch(emb.data_ptr<float>(), weight.data_ptr<float>(), bias.data_ptr<float>(), outs, B,
                         ws.data_ptr(), ws_bytes, stream);
  TORCH_CHECK(st == 0, "cublasLtMatmul failed with status ", st);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) { m.def("run", &run, "AdaLayerNormZero modulation extraction (cuBLASLt fp32)"); }

#include <cuda_runtime.h>
#include <cublasLt.h>
#include <cstdint>
#include <cstdio>
#include <map>
#include <mutex>

// AdaLayerNormZero modulation: out_i = emb @ W_i^T + bias_i for i in 0..5, fp32 FFMA (CUBLAS_COMPUTE_32F).
// Column-major view: D_i (N x B, ld N) = op_T(W_i as K x N, ld K) * (emb as K x B, ld K) + bias_i (per row).

namespace {
constexpr int kD = 3072;   // inner_dim
constexpr int kChunks = 6;

struct Plan {
  cublasLtMatmulDesc_t desc = nullptr;
  cublasLtMatrixLayout_t la = nullptr, lb = nullptr, lc = nullptr;
  cublasLtMatmulAlgo_t algo;
  bool have_algo = false;
};

cublasLtHandle_t g_handle = nullptr;
std::mutex g_mu;
std::map<int, Plan> g_plans;   // keyed on batch size (shape only)

Plan& get_plan(int B, size_t ws_bytes) {
  std::lock_guard<std::mutex> lk(g_mu);
  if (!g_handle) cublasLtCreate(&g_handle);
  auto it = g_plans.find(B);
  if (it != g_plans.end()) return it->second;
  Plan p;
  cublasLtMatmulDescCreate(&p.desc, CUBLAS_COMPUTE_32F, CUDA_R_32F);
  cublasOperation_t ta = CUBLAS_OP_T, tb = CUBLAS_OP_N;
  cublasLtMatmulDescSetAttribute(p.desc, CUBLASLT_MATMUL_DESC_TRANSA, &ta, sizeof(ta));
  cublasLtMatmulDescSetAttribute(p.desc, CUBLASLT_MATMUL_DESC_TRANSB, &tb, sizeof(tb));
  cublasLtEpilogue_t epi = CUBLASLT_EPILOGUE_BIAS;
  cublasLtMatmulDescSetAttribute(p.desc, CUBLASLT_MATMUL_DESC_EPILOGUE, &epi, sizeof(epi));
  // A = W_i stored as K x N (row-major [N,K]), B = emb stored as K x B (row-major [B,K]), D = N x B (row-major [B,N]).
  cublasLtMatrixLayoutCreate(&p.la, CUDA_R_32F, kD, kD, kD);
  cublasLtMatrixLayoutCreate(&p.lb, CUDA_R_32F, kD, B, kD);
  cublasLtMatrixLayoutCreate(&p.lc, CUDA_R_32F, kD, B, kD);
  cublasLtMatmulPreference_t pref;
  cublasLtMatmulPreferenceCreate(&pref);
  cublasLtMatmulPreferenceSetAttribute(pref, CUBLASLT_MATMUL_PREF_MAX_WORKSPACE_BYTES, &ws_bytes, sizeof(ws_bytes));
  cublasLtMatmulHeuristicResult_t res[1];
  int n = 0;
  if (cublasLtMatmulAlgoGetHeuristic(g_handle, p.desc, p.la, p.lb, p.lc, p.lc, pref, 1, res, &n) == CUBLAS_STATUS_SUCCESS && n > 0) {
    p.algo = res[0].algo;
    p.have_algo = true;
  }
  cublasLtMatmulPreferenceDestroy(pref);
  return g_plans.emplace(B, p).first->second;
}
}  // namespace

extern "C" int adamod_launch(const float* emb, const float* weight, const float* bias, float* const* outs, int B,
                             void* ws, size_t ws_bytes, cudaStream_t stream) {
  Plan& p = get_plan(B, ws_bytes);
  const float alpha = 1.f, beta = 0.f;
  for (int i = 0; i < kChunks; ++i) {
    const float* wi = weight + (size_t)i * kD * kD;
    const float* bi = bias + (size_t)i * kD;
    float* di = outs[i];
    {
      std::lock_guard<std::mutex> lk(g_mu);
      cublasLtMatmulDescSetAttribute(p.desc, CUBLASLT_MATMUL_DESC_BIAS_POINTER, &bi, sizeof(bi));
      cublasStatus_t st = cublasLtMatmul(g_handle, p.desc, &alpha, wi, p.la, emb, p.lb, &beta, di, p.lc, di, p.lc,
                                         p.have_algo ? &p.algo : nullptr, ws, ws_bytes, stream);
      if (st != CUBLAS_STATUS_SUCCESS) return (int)st;
    }
  }
  return 0;
}

