D=3072; N=6*D
src_t = r'''
#define NB %d
#define ROWS 128
#define KC 64
#define STAGES 3
#define RS (KC*4+16)
__device__ __forceinline__ void cp_async16(void* smem, const void* g) {
  unsigned s = (unsigned)__cvta_generic_to_shared(smem);
  asm volatile("cp.async.cg.shared.global [%%0], [%%1], 16;" :: "r"(s), "l"(g));
