  const int rg = warp & 3, kh = warp >> 2;
  const int n0 = blockIdx.x * ROWS;
  const float* Wb = W + (size_t)n0 * 3072;
  float acc[NB];
  #pragma unroll
  for (int b = 0; b < NB; b++) acc[b] = 0.f;
  const int NKC = 3072 / KC;
  auto load_stage = [&](int s, int kc) {
    #pragma unroll
    for (int i = 0; i < 8; i++) {
      int c = tid + i*256; int r = c >> 4, q = c & 15;
      cp_async16(wbuf + (size_t)s*ROWS*RS + r*RS + q*16, Wb + (size_t)r*3072 + kc + q*4);
    }
    for (int c = tid; c < NB*16; c += 256) { int b = c >> 4, q = c & 15; cp_async16(ebuf + (s*NB + b)*KC + q*4, emb + (size_t)b*3072 + kc + q*4); }
  };
  #pragma unroll
  for (int s = 0; s < STAGES-1; s++) { load_stage(s, s*KC); asm volatile("cp.async.commit_group;"); }
  for (int it = 0; it < NKC; it++) {
    asm volatile("cp.async.wait_group %%0;" :: "n"(STAGES-2));
