    emb = torch.randn(B, D, device='cuda'); w = torch.randn(N, D, device='cuda')/(D)**0.5; b = torch.randn(N, device='cuda')
    outs = [torch.empty(B, D, device='cuda') for _ in range(6)]
    ref = (emb.double() @ w.double().t() + b.double())
    def fn(emb, w, b, *outs):
        k((N//128,1,1),(256,1,1), w, emb, b, *outs, shared_mem=smem)
    try:
        fn(emb, w, b, *outs); torch.cuda.synchronize()
    except Exception as e:
        print('launch err', e); 
        import inspect; print(inspect.signature(k)); raise
    got = torch.cat(outs, dim=1).double()
    err = (got-ref).abs().max().item()
    t = harness_time(fn, [emb,w,b], outs)
    print(f"B={B}: skinny {t:.1f} us  maxerr {err:.2e}  smem {smem}")
print(resources(src_t % 32))

