    if (nxt < NKC) load_stage(nxt %% STAGES, nxt*KC);
    asm volatile("cp.async.commit_group;");
    int s = it %% STAGES;
    const float4* wrow = (const float4*)(wbuf + (size_t)s*ROWS*RS + (rg*32+lane)*RS) + kh*8;
    const float4* eb = (const float4*)(ebuf + s*NB*KC) + kh*8;
    #pragma unroll
    for (int q = 0; q < 8; q++) {
      float4 w = wrow[q];
      #pragma unroll
      for (int b = 0; b < NB; b++) { float4 e = eb[b*16 + q]; acc[b] = fmaf(w.x,e.x,acc[b]); acc[b] = fmaf(w.y,e.y,acc[b]); acc[b] = fmaf(w.z,e.z,acc[b]); acc[b] = fmaf(w.w,e.w,acc[b]); }
    }
