  if (adamod_uses_tf32(B)) { whi = torch::empty_like(weight); wlo = torch::empty_like(weight); ehi = torch::empty_like(emb); elo = torch::empty_like(emb); pwhi = whi.data_ptr<float>(); pwlo = wlo.data_ptr<float>(); pehi = ehi.data_ptr<float>(); pelo = elo.data_ptr<float>(); }
